WITH flattened_attrs AS (SELECT id, plan, tier_limits, tier_prices, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT plan, PERCENTILE_APPROX(entry_price, 0.5) AS entry_price_p50, COUNT(CASE WHEN plan = 'pro' THEN 1 END) AS pro_count, APPROX_PERCENTILE(entry_price, 0.5) AS entry_price_p50_2, COUNT(*) AS cnt FROM flattened_attrs GROUP BY plan ORDER BY plan DESC NULLS LAST
